WITH parsed AS (SELECT id, host, level, status_code, payload_json, context, COALESCE(context['version'], 'unknown') AS version_or_default, COALESCE(context['trace'], 'unknown') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT CASE WHEN duration_sec >= 3.7 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, host, level, APPROX_PERCENTILE(duration_sec, 0.95) AS duration_sec_p95, ROUND(AVG(status_code), 2) AS avg_status_code, GROUPING_ID() AS grouping_level FROM parsed GROUP BY ROLLUP (CASE WHEN duration_sec >= 3.7 THEN 'HIGH' ELSE 'LOW' END, host, level) ORDER BY duration_sec_p95 DESC;
